class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_len = -1

        for char_code in range(ord('a'), ord('z') + 1):
            char = chr(char_code)
            counts = {}
            current_streak = 0

            for i in range(n):
                if s[i] == char:
                    current_streak += 1
                else:
                    if current_streak > 0:
                        for length in range(1, current_streak + 1):
                            counts[length] = counts.get(length, 0) + (current_streak - length + 1)
                    current_streak = 0

            if current_streak > 0:
                for length in range(1, current_streak + 1):
                    counts[length] = counts.get(length, 0) + (current_streak - length + 1)

            for length in sorted(counts.keys(), reverse=True):
                if counts[length] >= 3:
                    max_len = max(max_len, length)
                    break

        return max_len

